package cn.binbin.crm;

import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.constraints.*;
import java.time.*;
import java.util.*;
import java.util.function.Function;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class ConfigurationService {
 public record ProfileInput(@NotBlank @Size(max=100) String brandName,@Email @Size(max=254) String supportEmail,boolean portalEnabled,@Min(0) long expectedVersion){}
 public record FieldInput(@NotNull @Pattern(regexp="CUSTOMER|CONTACT|LEAD|OPPORTUNITY|TICKET|QUOTE|ORDER|CONTRACT|RECEIPT|INVOICE|EXPENSE|TARGET|COMMISSION|WEEKLY|PRODUCT") String entityType,@NotBlank @Pattern(regexp="[a-z][a-z0-9_]{1,39}") String fieldKey,@NotBlank @Size(max=80) String label,@NotNull @Pattern(regexp="TEXT|TEXTAREA|NUMBER|DATE|BOOLEAN|SELECT|MULTI_SELECT") String dataType,boolean required,@NotBlank @Size(max=80) String sectionName,@Min(0) @Max(10000) int position,@Size(max=100) List<@Size(max=100) String> options,@NotEmpty Set<@Pattern(regexp="TENANT_ADMIN|SALES_MANAGER|SALES|VIEWER") String> readRoles,@NotEmpty Set<@Pattern(regexp="TENANT_ADMIN|SALES_MANAGER|SALES|VIEWER") String> writeRoles,@NotNull @Pattern(regexp="ACTIVE|ARCHIVED") String status,@Min(0) long expectedVersion){}
 public record TagInput(@NotBlank @Size(max=40) String name,@NotNull @Pattern(regexp="#[0-9A-Fa-f]{6}") String color,@NotNull @Pattern(regexp="ACTIVE|ARCHIVED") String status,@Min(0) long expectedVersion){}
 public record StageInput(@NotBlank @Size(max=80) String label,@Min(0) @Max(1000) int position,@Min(0) @Max(100) int probability,boolean active,@Min(0) long expectedVersion){}
 public record NumberInput(@NotNull @Pattern(regexp="[A-Z0-9]{1,10}") String prefix,boolean includeYear,@Min(3) @Max(9) int padding,@Min(0) long expectedVersion){}
 public record ApprovalInput(@NotBlank @Size(max=100) String name,@Min(0) @Max(100000000000L) long minimumAmountCents,boolean active,@Min(0) long expectedVersion){}
 public record DictionaryInput(@NotBlank @Pattern(regexp="[A-Z0-9_]{1,40}") String itemCode,@NotBlank @Size(max=80) String label,@Min(0) @Max(10000) int position,boolean active,@Min(0) long expectedVersion){}
 public record CustomerExtensionInput(Map<UUID,Object> values,Set<UUID> tagIds){}
 private final NamedParameterJdbcTemplate db;private final TransactionTemplate tx;private final AuthService auth;private final ObjectMapper json;private final CustomerService customers;
 public ConfigurationService(NamedParameterJdbcTemplate db,TransactionTemplate tx,AuthService auth,ObjectMapper json,CustomerService customers){this.db=db;this.tx=tx;this.auth=auth;this.json=json;this.customers=customers;}
 private static Map<String,Object> p(Object... v){return SaasService.parameters(v);}private static String text(String v){return v==null?"":v.strip();}
 private Map<String,Object> view(Map<String,Object> raw){var out=SaasService.view(raw);out.replaceAll((key,value)->{if(value!=null&&value.getClass().getName().equals("org.postgresql.util.PGobject"))try{return json.readValue(String.valueOf(value),Object.class);}catch(Exception e){throw new IllegalStateException(e);}return value;});return out;}
 private List<Map<String,Object>> rows(String sql,Map<String,?> p){return db.queryForList(sql,p).stream().map(this::view).toList();}
 private Map<String,Object> one(String sql,Map<String,?> p){var r=db.queryForList(sql,p);if(r.isEmpty())throw ApiError.missing();return r.getFirst();}
 private <T>T scoped(AuthService.Session s,boolean write,Function<AuthService.Actor,T> fn){return tx.execute(st->{if(write&&s.tenantId()!=null)db.queryForObject("SELECT id FROM sys_tenant WHERE id=:id FOR UPDATE",Map.of("id",s.tenantId()),UUID.class);var a=auth.actor(s);if(a.supportGrantId()!=null||!a.p4Access().configurationRead()||write&&!a.p4Access().configurationManage())throw ApiError.forbidden("当前角色没有配置中心权限");if(!Boolean.TRUE.equals(db.queryForObject("SELECT p.configuration_enabled FROM sys_tenant t JOIN sys_plan p ON p.id=t.plan_id WHERE t.id=:id",Map.of("id",a.tenant().id()),Boolean.class)))throw ApiError.forbidden("当前套餐未启用行业配置中心");if(write&&!a.tenant().subscriptionEnd().isAfter(Instant.now()))throw ApiError.forbidden("订阅到期，配置中心仅可查看");db.queryForObject("SELECT set_config('crm.tenant_id',:id,true)",Map.of("id",a.tenant().id().toString()),String.class);return fn.apply(a);});}
 private void audit(AuthService.Actor a,String action,String type,UUID id,long version,UUID trace){DataService.audit(db,a,action,type,id,version,trace);}
 private UUID once(AuthService.Actor a,String operation,String key,Object input,java.util.function.Supplier<UUID> create){if(key==null||!key.matches("[A-Za-z0-9_.:-]{1,100}"))throw ApiError.bad("请求编号无效");String hash=Crypto.hash(toJson(input));var q=p("tenant",a.tenant().id(),"member",a.tenant().memberId(),"op",operation,"key",key,"hash",hash);db.update("INSERT INTO sys_idempotency_request(tenant_id,member_id,operation,request_key,request_hash) VALUES(:tenant,:member,:op,:key,:hash) ON CONFLICT DO NOTHING",q);var previous=one("SELECT request_hash,result_id FROM sys_idempotency_request WHERE tenant_id=:tenant AND member_id=:member AND operation=:op AND request_key=:key FOR UPDATE",q);if(!hash.equals(previous.get("request_hash")))throw ApiError.conflict("相同请求编号对应的内容已变化");if(previous.get("result_id")!=null)return (UUID)previous.get("result_id");UUID result=create.get();q.put("result",result);db.update("UPDATE sys_idempotency_request SET result_id=:result WHERE tenant_id=:tenant AND member_id=:member AND operation=:op AND request_key=:key",q);return result;}
 public Object overview(AuthService.Session s){return scoped(s,false,a->p("profile",view(one("SELECT * FROM sys_tenant_profile WHERE tenant_id=:tenant",p("tenant",a.tenant().id()))),"templates",rows("SELECT code,name,description,version FROM sys_industry_template WHERE active ORDER BY code",Map.of()),"fields",rows("SELECT * FROM crm_custom_field WHERE tenant_id=:tenant ORDER BY entity_type,section_name,position,id",p("tenant",a.tenant().id())),"tags",rows("SELECT * FROM crm_tag WHERE tenant_id=:tenant ORDER BY status,name,id",p("tenant",a.tenant().id())),"stages",rows("SELECT * FROM crm_process_stage WHERE tenant_id=:tenant ORDER BY process_type,position,id",p("tenant",a.tenant().id())),"numberRules",rows("SELECT * FROM crm_number_rule WHERE tenant_id=:tenant ORDER BY document_type",p("tenant",a.tenant().id())),"approvalRule",view(one("SELECT * FROM crm_approval_rule WHERE tenant_id=:tenant AND process_type='QUOTE'",p("tenant",a.tenant().id()))),"dictionaries",rows("SELECT * FROM crm_dictionary_item WHERE tenant_id=:tenant ORDER BY dictionary_type,position,id",p("tenant",a.tenant().id()))));}
 public Object profile(AuthService.Session s,ProfileInput i,UUID trace){return scoped(s,true,a->{int n=db.update("UPDATE sys_tenant_profile SET brand_name=:brand,support_email=:email,portal_enabled=:portal,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND version=:version",p("brand",text(i.brandName()),"email",text(i.supportEmail()).toLowerCase(Locale.ROOT),"portal",i.portalEnabled(),"tenant",a.tenant().id(),"version",i.expectedVersion()));if(n!=1)throw ApiError.conflict("企业外观配置已变化，请刷新");audit(a,"CONFIG_PROFILE_UPDATED","TENANT_PROFILE",a.tenant().id(),i.expectedVersion()+1,trace);return view(one("SELECT * FROM sys_tenant_profile WHERE tenant_id=:tenant",p("tenant",a.tenant().id())));});}
 @SuppressWarnings("unchecked") public Object applyTemplate(AuthService.Session s,String code,UUID trace){return scoped(s,true,a->{var template=one("SELECT * FROM sys_industry_template WHERE code=:code AND active",p("code",code));Map<String,Object> definition;try{definition=json.readValue(String.valueOf(template.get("definition")),Map.class);}catch(Exception e){throw new IllegalStateException(e);}int fields=0,types=0;for(Object raw:(List<?>)definition.getOrDefault("fields",List.of())){var f=(List<?>)raw;String data=String.valueOf(f.get(3));List<String> options=List.of();if(data.equals("SELECT")||data.equals("MULTI_SELECT")){data="TEXT";}int n=db.update("INSERT INTO crm_custom_field(id,tenant_id,entity_type,field_key,label,data_type,section_name,position,options) VALUES(:id,:tenant,:entity,:key,:label,:data,:section,:position,cast(:options AS jsonb)) ON CONFLICT(tenant_id,entity_type,field_key) DO NOTHING",p("id",UUID.randomUUID(),"tenant",a.tenant().id(),"entity",f.get(0),"key",f.get(1),"label",f.get(2),"data",data,"section",f.get(4),"position",100+fields*10,"options",toJson(options)));fields+=n;}int position=10;for(Object raw:(List<?>)definition.getOrDefault("ticketTypes",List.of())){var d=(List<?>)raw;int n=db.update("INSERT INTO crm_dictionary_item(id,tenant_id,dictionary_type,item_code,label,position) VALUES(:id,:tenant,'TICKET_TYPE',:code,:label,:position) ON CONFLICT(tenant_id,dictionary_type,item_code) DO UPDATE SET label=excluded.label,active=true,version=crm_dictionary_item.version+1,updated_at=now()",p("id",UUID.randomUUID(),"tenant",a.tenant().id(),"code",d.get(0),"label",d.get(1),"position",position));types+=n;position+=10;}db.update("UPDATE sys_tenant_profile SET industry_template_code=:code,version=version+1,updated_at=now() WHERE tenant_id=:tenant",p("code",code,"tenant",a.tenant().id()));audit(a,"INDUSTRY_TEMPLATE_APPLIED","TENANT_PROFILE",a.tenant().id(),0,trace);return p("code",code,"fieldsCreated",fields,"ticketTypesApplied",types);});}
 private String toJson(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}}
 public Object field(AuthService.Session s,UUID id,FieldInput i,String key,UUID trace){if((i.dataType().equals("SELECT")||i.dataType().equals("MULTI_SELECT"))&&(i.options()==null||i.options().isEmpty()))throw ApiError.bad("选择字段至少需要一个选项");if(!i.readRoles().containsAll(i.writeRoles()))throw ApiError.bad("字段可编辑角色必须同时拥有读取权限");return scoped(s,true,a->{UUID selected=id;if(id==null){selected=once(a,"configuration.field.create",key,i,()->{UUID created=UUID.randomUUID();db.update("INSERT INTO crm_custom_field(id,tenant_id,entity_type,field_key,label,data_type,required,section_name,position,options,read_roles,write_roles,status) VALUES(:id,:tenant,:entity,:key,:label,:data,:required,:section,:position,cast(:options AS jsonb),:reads,:writes,:status)",fieldParams(a,created,i));return created;});}else{var q=fieldParams(a,id,i);q.put("version",i.expectedVersion());if(db.update("UPDATE crm_custom_field SET label=:label,required=:required,section_name=:section,position=:position,options=cast(:options AS jsonb),read_roles=:reads,write_roles=:writes,status=:status,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version AND entity_type=:entity AND field_key=:key AND data_type=:data",q)!=1)throw ApiError.conflict("自定义字段已变化，字段编码和类型不可修改");}audit(a,id==null?"CUSTOM_FIELD_CREATED":"CUSTOM_FIELD_UPDATED","CUSTOM_FIELD",selected,id==null?0:i.expectedVersion()+1,trace);return view(one("SELECT * FROM crm_custom_field WHERE tenant_id=:tenant AND id=:id",p("tenant",a.tenant().id(),"id",selected)));});}
 private Map<String,Object> fieldParams(AuthService.Actor a,UUID id,FieldInput i){return p("id",id,"tenant",a.tenant().id(),"entity",i.entityType(),"key",i.fieldKey(),"label",text(i.label()),"data",i.dataType(),"required",i.required(),"section",text(i.sectionName()),"position",i.position(),"options",toJson(i.options()==null?List.of():i.options().stream().map(String::strip).filter(v->!v.isEmpty()).distinct().toList()),"reads",i.readRoles().toArray(String[]::new),"writes",i.writeRoles().toArray(String[]::new),"status",i.status());}
 public Object tag(AuthService.Session s,UUID id,TagInput i,String key,UUID trace){return scoped(s,true,a->{UUID selected=id;if(id==null){selected=once(a,"configuration.tag.create",key,i,()->{UUID created=UUID.randomUUID();db.update("INSERT INTO crm_tag(id,tenant_id,name,color,status) VALUES(:id,:tenant,:name,:color,:status)",p("id",created,"tenant",a.tenant().id(),"name",text(i.name()),"color",i.color().toUpperCase(Locale.ROOT),"status",i.status()));return created;});}else if(db.update("UPDATE crm_tag SET name=:name,color=:color,status=:status,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version",p("id",id,"tenant",a.tenant().id(),"name",text(i.name()),"color",i.color().toUpperCase(Locale.ROOT),"status",i.status(),"version",i.expectedVersion()))!=1)throw ApiError.conflict("客户标签已变化");audit(a,id==null?"TAG_CREATED":"TAG_UPDATED","TAG",selected,id==null?0:i.expectedVersion()+1,trace);return view(one("SELECT * FROM crm_tag WHERE tenant_id=:tenant AND id=:id",p("tenant",a.tenant().id(),"id",selected)));});}
 public Object stage(AuthService.Session s,UUID id,StageInput i,UUID trace){return scoped(s,true,a->{var old=one("SELECT * FROM crm_process_stage WHERE tenant_id=:tenant AND id=:id",p("tenant",a.tenant().id(),"id",id));if(Boolean.TRUE.equals(old.get("terminal"))&&!i.active())throw ApiError.bad("结束阶段不能停用");if(db.update("UPDATE crm_process_stage SET label=:label,position=:position,probability=:probability,active=:active,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version",p("label",text(i.label()),"position",i.position(),"probability",i.probability(),"active",i.active(),"tenant",a.tenant().id(),"id",id,"version",i.expectedVersion()))!=1)throw ApiError.conflict("阶段配置已变化");audit(a,"PROCESS_STAGE_UPDATED","PROCESS_STAGE",id,i.expectedVersion()+1,trace);return view(one("SELECT * FROM crm_process_stage WHERE tenant_id=:tenant AND id=:id",p("tenant",a.tenant().id(),"id",id)));});}
 public Object number(AuthService.Session s,UUID id,NumberInput i,UUID trace){return scoped(s,true,a->{if(db.update("UPDATE crm_number_rule SET prefix=:prefix,include_year=:year,padding=:padding,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version",p("prefix",i.prefix(),"year",i.includeYear(),"padding",i.padding(),"tenant",a.tenant().id(),"id",id,"version",i.expectedVersion()))!=1)throw ApiError.conflict("编号规则已变化");audit(a,"NUMBER_RULE_UPDATED","NUMBER_RULE",id,i.expectedVersion()+1,trace);return view(one("SELECT * FROM crm_number_rule WHERE tenant_id=:tenant AND id=:id",p("tenant",a.tenant().id(),"id",id)));});}
 public Object approval(AuthService.Session s,UUID id,ApprovalInput i,UUID trace){return scoped(s,true,a->{if(db.update("UPDATE crm_approval_rule SET name=:name,minimum_amount_cents=:amount,active=:active,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version",p("name",text(i.name()),"amount",i.minimumAmountCents(),"active",i.active(),"tenant",a.tenant().id(),"id",id,"version",i.expectedVersion()))!=1)throw ApiError.conflict("审批规则已变化");audit(a,"APPROVAL_RULE_UPDATED","APPROVAL_RULE",id,i.expectedVersion()+1,trace);return view(one("SELECT * FROM crm_approval_rule WHERE tenant_id=:tenant AND id=:id",p("tenant",a.tenant().id(),"id",id)));});}
 public Object dictionary(AuthService.Session s,String type,UUID id,DictionaryInput i,String key,UUID trace){if(!Set.of("TICKET_TYPE","CUSTOMER_INDUSTRY","LEAD_SOURCE").contains(type))throw ApiError.bad("字典类型无效");return scoped(s,true,a->{UUID selected=id;if(id==null){selected=once(a,"configuration.dictionary."+type.toLowerCase(Locale.ROOT)+".create",key,i,()->{UUID created=UUID.randomUUID();db.update("INSERT INTO crm_dictionary_item(id,tenant_id,dictionary_type,item_code,label,position,active) VALUES(:id,:tenant,:type,:code,:label,:position,:active)",p("id",created,"tenant",a.tenant().id(),"type",type,"code",i.itemCode(),"label",text(i.label()),"position",i.position(),"active",i.active()));return created;});}else if(db.update("UPDATE crm_dictionary_item SET label=:label,position=:position,active=:active,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version AND dictionary_type=:type AND item_code=:code",p("id",id,"tenant",a.tenant().id(),"type",type,"code",i.itemCode(),"label",text(i.label()),"position",i.position(),"active",i.active(),"version",i.expectedVersion()))!=1)throw ApiError.conflict("字典项已变化，编码不可修改");audit(a,id==null?"DICTIONARY_CREATED":"DICTIONARY_UPDATED","DICTIONARY",selected,id==null?0:i.expectedVersion()+1,trace);return view(one("SELECT * FROM crm_dictionary_item WHERE tenant_id=:tenant AND id=:id",p("tenant",a.tenant().id(),"id",selected)));});}
 public Object extensions(AuthService.Session s,UUID customer){return tx.execute(st->{var a=auth.actor(s);if(a.supportGrantId()!=null)throw ApiError.forbidden("支持授权不含扩展资料");db.queryForObject("SELECT set_config('crm.tenant_id',:id,true)",p("id",a.tenant().id().toString()),String.class);customers.get(a,customer);Set<String> roles=a.tenant().roles();var fields=rows("SELECT * FROM crm_custom_field WHERE tenant_id=:tenant AND entity_type='CUSTOMER' AND status='ACTIVE' AND read_roles&&:roles ORDER BY section_name,position,id",p("tenant",a.tenant().id(),"roles",roles.toArray(String[]::new)));var values=rows("SELECT v.field_id,v.value FROM crm_custom_value v JOIN crm_custom_field f ON f.tenant_id=v.tenant_id AND f.id=v.field_id WHERE v.tenant_id=:tenant AND v.entity_type='CUSTOMER' AND v.record_id=:id AND f.status='ACTIVE' AND f.read_roles&&:roles",p("tenant",a.tenant().id(),"id",customer,"roles",roles.toArray(String[]::new)));var tags=rows("SELECT t.*,ct.customer_id IS NOT NULL AS assigned FROM crm_tag t LEFT JOIN crm_customer_tag ct ON ct.tenant_id=t.tenant_id AND ct.tag_id=t.id AND ct.customer_id=:id WHERE t.tenant_id=:tenant AND t.status='ACTIVE' ORDER BY t.name",p("tenant",a.tenant().id(),"id",customer));return p("fields",fields,"values",values,"tags",tags);});}
 public Object saveExtensions(AuthService.Session s,UUID customer,CustomerExtensionInput i,UUID trace){return tx.execute(st->{var a=auth.actor(s);a.requireWrite();db.queryForObject("SELECT set_config('crm.tenant_id',:id,true)",p("id",a.tenant().id().toString()),String.class);if(!customers.get(a,customer).canWrite())throw ApiError.forbidden("无权编辑该客户扩展资料");for(var e:(i.values()==null?Map.<UUID,Object>of():i.values()).entrySet()){var f=one("SELECT * FROM crm_custom_field WHERE tenant_id=:tenant AND id=:id AND entity_type='CUSTOMER' AND status='ACTIVE' AND write_roles&&:roles",p("tenant",a.tenant().id(),"id",e.getKey(),"roles",a.tenant().roles().toArray(String[]::new)));validateValue(f,e.getValue());if(e.getValue()==null||String.valueOf(e.getValue()).isBlank())db.update("DELETE FROM crm_custom_value WHERE tenant_id=:tenant AND field_id=:field AND record_id=:record",p("tenant",a.tenant().id(),"field",e.getKey(),"record",customer));else db.update("INSERT INTO crm_custom_value(id,tenant_id,field_id,entity_type,record_id,value,updated_by_member_id) VALUES(:id,:tenant,:field,'CUSTOMER',:record,cast(:value AS jsonb),:member) ON CONFLICT(tenant_id,field_id,record_id) DO UPDATE SET value=excluded.value,updated_by_member_id=excluded.updated_by_member_id,version=crm_custom_value.version+1,updated_at=now()",p("id",UUID.randomUUID(),"tenant",a.tenant().id(),"field",e.getKey(),"record",customer,"value",toJson(e.getValue()),"member",a.tenant().memberId()));}if(i.tagIds()!=null){db.update("DELETE FROM crm_customer_tag WHERE tenant_id=:tenant AND customer_id=:customer",p("tenant",a.tenant().id(),"customer",customer));for(UUID tag:i.tagIds())db.update("INSERT INTO crm_customer_tag(tenant_id,customer_id,tag_id,assigned_by_member_id) SELECT :tenant,:customer,id,:member FROM crm_tag WHERE tenant_id=:tenant AND id=:tag AND status='ACTIVE'",p("tenant",a.tenant().id(),"customer",customer,"member",a.tenant().memberId(),"tag",tag));}audit(a,"CUSTOMER_EXTENSIONS_UPDATED","CUSTOMER",customer,0,trace);return extensions(s,customer);});}
 private void validateValue(Map<String,Object> f,Object value){if(value==null)return;String type=String.valueOf(f.get("data_type"));boolean ok=switch(type){case "NUMBER"->value instanceof Number||String.valueOf(value).matches("-?[0-9]+(\\.[0-9]+)?");case "BOOLEAN"->value instanceof Boolean;case "MULTI_SELECT"->value instanceof Collection<?>;default->value instanceof String;};if(!ok)throw ApiError.bad("字段“"+f.get("label")+"”的值类型无效");String s=String.valueOf(value);if(s.length()>4000)throw ApiError.bad("自定义字段内容过长");}
}
